import{St as e,at as t,et as n,it as r,n as i,ot as a,rt as o,vt as s}from"./chunks/framework.CoUqiBXn.js";var c=JSON.parse(`{"title":"FAQs for SysReptor Cloud","description":"","frontmatter":{},"headers":[],"relativePath":"faq/cloud.md","filePath":"faq/cloud.md","lastUpdated":1789544512000}`),l={name:`faq/cloud.md`},u={class:`info custom-block`},d={class:`custom-block-title`};function f(i,c,l,f,p,m){let h=e(`FaqExpandAll`),g=e(`DocBadge`);return s(),o(`div`,null,[c[1]||=r(`<h1 id="faqs-for-sysreptor-cloud" tabindex="-1">FAQs for SysReptor Cloud <a class="header-anchor" href="#faqs-for-sysreptor-cloud" aria-label="Permalink to “FAQs for SysReptor Cloud”">​</a></h1><p>These FAQs are for <strong>SysReptor Cloud</strong> (hosted by Syslifters for organizations).</p><p>If you write <strong>HTB, OffSec, or other exam reports</strong> on <a href="https://labs.sysre.pt" target="_blank" rel="noreferrer">labs.sysre.pt</a>, use the <a href="/faq/exam-reports">exam report FAQs</a> instead. Self-hosted Docker installs are covered in the <a href="/faq/self-hosted">self-hosted FAQs</a>.</p>`,3),a(h),c[2]||=r(`<div class="faq-item"><details class="details custom-block"><summary>What is SysReptor Cloud compared to self-hosted SysReptor and labs.sysre.pt?</summary><p>There are three common ways to use SysReptor:</p><ul><li><strong>Self-hosted:</strong> you install SysReptor with Docker on your own server. Self-hosted can be SysReptor Community (free) or SysReptor Professional (paid). See <a href="/setup/installation">Installation</a>, <a href="https://sysreptor.com/pricing" target="_blank" rel="noreferrer">pricing</a> and <a href="/faq/self-hosted">self-hosted FAQs</a>.</li><li><strong>SysReptor Cloud:</strong> Syslifters hosts SysReptor Professional for your organization (paid). See <a href="https://sysreptor.com/pricing" target="_blank" rel="noreferrer">pricing</a>.</li><li><strong>SysReptor Labs:</strong> the free exam-reporting service at <a href="https://labs.sysre.pt" target="_blank" rel="noreferrer">labs.sysre.pt</a> hosted in the SysReptor Cloud for students writing certification and exam reports. See the <a href="/faq/exam-reports">exam report FAQs</a>.</li></ul><p>The <a href="https://sysreptor.com/demo" target="_blank" rel="noreferrer">public playground</a> is a demo installation hosted in the SysReptor Cloud.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>Is SysReptor Cloud free?</summary><p>SysReptor Cloud is a paid hosted offering. See <a href="https://sysreptor.com/pricing" target="_blank" rel="noreferrer">pricing</a>.</p><p><strong>SysReptor Labs</strong> at <a href="https://labs.sysre.pt" target="_blank" rel="noreferrer">labs.sysre.pt</a> for HTB/OffSec students is free; that is a non-commercial service.</p></details></div><div class="faq-item" id="hosted"><details class="details custom-block"><summary>Where is SysReptor Cloud hosted?</summary><p>SysReptor Cloud currently runs in <strong>Germany</strong> on physical servers at <a href="https://www.hetzner.com/" target="_blank" rel="noreferrer">Hetzner Online GmbH</a>. We operate a self-managed Kubernetes cluster there on physical servers.<br> We guarantee that if new sites are added in the future, their location will be within the European Union (EU).</p></details></div><div class="faq-item" id="privacy-laws"><details class="details custom-block"><summary>What data privacy laws apply?</summary><p>Personal data in Cloud is processed under the <strong>GDPR</strong>. The Cloud contract is governed by Austrian law.</p></details></div><div class="faq-item" id="dpa"><details class="details custom-block"><summary>Can I have a signed DPA (AVV)?</summary><p>Yes. Please <a href="/contact-us#contact-information">contact us</a>.</p></details></div><div class="faq-item" id="eu-data"><details class="details custom-block"><summary>Does any Cloud customer data leave the EU/EEA?</summary><p>No.</p></details></div><div class="faq-item" id="encryption"><details class="details custom-block"><summary>Is data encrypted in transit and at rest?</summary><p>Yes. Data in transit is encrypted with <strong>HTTPS</strong>. At rest, all data is stored on an encrypted <strong>ZFS</strong> partition. In addition, every Cloud installation has its own encryption key for database and file/asset encryption. See <a href="/setup/configuration#data-encryption-at-rest">Data Encryption at Rest</a>.</p></details></div><div class="faq-item" id="tenant-isolation"><details class="details custom-block"><summary>Are Cloud tenants isolated from each other?</summary><p>Yes. Each customer runs in a dedicated Kubernetes namespace with network separation. Each installation uses its own encryption keys.</p><p>PDF rendering pods are shared, but each pod is disposed after one use so rendering jobs cannot interfere with another customer. See <a href="/insights/architecture">Architecture</a>.</p></details></div><div class="faq-item" id="third-parties"><details class="details custom-block"><summary>Does SysReptor send report contents to third parties, e.g., for spell check or AI?</summary><p>No. Spell check runs inside your Cloud installation (<a href="/reporting/spell-check">LanguageTool</a>). Report content is sent to an LLM only if you <a href="/reporting/ai-agent">configure an AI provider</a> in settings.</p></details></div><div class="faq-item" id="ai-training"><details class="details custom-block"><summary>Do you use my reports to train AI models?</summary><p>No.</p></details></div><div class="faq-item" id="custom-domain"><details class="details custom-block"><summary>Can I use my own domain name for hosting?</summary><p>Yes. Please <a href="/contact-us#contact-information">contact us</a>.</p></details></div><div class="faq-item" id="sso"><details class="details custom-block"><summary>Can I require SSO (OIDC) and disable password login?</summary><p>Yes. Superusers can enable <a href="/users/oidc-setup">OIDC SSO</a> and disable username/password login in <strong>Settings → Authentication Settings</strong> (<code>LOCAL_USER_AUTH_ENABLED=false</code>). See <a href="/setup/configuration#single-sign-on-sso">SSO configuration</a>.<br> You can disable local user authentication for the entire installation, or on a per-user basis.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>Can I install plugins on SysReptor Cloud?</summary><p>Yes. <a href="/setup/plugins#official-plugins">Official plugins</a> that ship with SysReptor can be enabled in settings.</p><p><strong>Custom plugins</strong> are only supported in self-hosted SysReptor, not in the cloud version.</p></details></div><div class="faq-item" id="reptor-cli"><details class="details custom-block"><summary>Can Cloud users use the reptor CLI?</summary><p>Yes. Create an API token in your user profile and configure <code>reptor</code> with your Cloud URL. See the <a href="/cli/getting-started"><code>reptor</code> CLI documentation</a>.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>How do I reset my password on SysReptor Cloud?</summary><p>Administrators with superuser or user manager permissions can reset user passwords in the Users UI. See the <a href="/users/forgot-password#reset-password-via-user-admin-interface">full steps</a>.</p><p>If your cloud installation has the <strong>Forgot Password</strong> functionality enabled, you can use it to receive an email for setting a new password. You will still need your second authentication factor, if configured for your user account to successfully authenticate.</p><p>Students on SysReptor Labs can <a href="https://labs.sysre.pt/login/forgot-password/" target="_blank" rel="noreferrer">reset their password</a> online.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>Can I create backups of a SysReptor Cloud instance?</summary><p>Yes. You can <a href="/setup/backups#create-backups-via-web-interface">create a backup via web interface</a> with your SysReptor installation&#39;s <a href="/setup/configuration#backup-key"><code>BACKUP_KEY</code></a> and you must have <strong>superuser</strong> permissions. Please <a href="/contact-us#contact-information">contact us</a> to receive your <code>BACKUP_KEY</code>.</p><p>You can always <strong>export individual projects</strong> as <code>.tar.gz</code> from the projects list. This is not a full instance backup.</p></details></div><div class="faq-item" id="backups-location"><details class="details custom-block"><summary>Where are backups stored?</summary><p>On our own servers in Austria. Each backup is encrypted with a dedicated symmetric key. That key is encrypted with an asymmetric key. Private keys for recovering the symmetric encryption keys are stored on hardware tokens with PIN protection.</p></details></div><div class="faq-item" id="backup-retention"><details class="details custom-block"><summary>How long are backups stored?</summary><ul><li><strong>Daily backups:</strong> 21 days</li><li><strong>Weekly backups:</strong> 35 days</li><li><strong>Monthly backups:</strong> 365 days</li></ul></details></div><div class="faq-item" id="delete-instance"><details class="details custom-block"><summary>Can you delete my instance and confirm it?</summary><p>Yes. Please <a href="/contact-us#contact-information">contact us</a>. We can delete your Cloud instance and confirm the deletion.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>Can I migrate from SysReptor Cloud to a self-hosted SysReptor?</summary><p>Yes, you can <a href="/setup/backups#create-backups-via-web-interface">create a backup</a> and restore it on a self-hosted SysReptor installation.</p><p>You can also move project data by <strong>exporting projects</strong> from Cloud (projects list → export <code>.tar.gz</code>) and <strong>importing</strong> them on a <a href="/setup/installation">self-hosted</a> instance.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>Can I migrate from a self-hosted SysReptor to SysReptor Cloud?</summary><p>Yes, you can <a href="/setup/backups">create a backup</a> and <a href="/contact-us#contact-information">contact us</a> to restore it on a SysReptor Cloud installation.</p><p>You can also move project data by <strong>exporting projects</strong> from self-hosted (projects list → export <code>.tar.gz</code>) and <strong>importing</strong> them on Cloud.</p></details></div><div class="faq-item" id="availability"><details class="details custom-block"><summary>Is there a track record for SysReptor Cloud&#39;s availability?</summary><p>Yes. See the <a href="https://status.sysreptor.com/" target="_blank" rel="noreferrer">SysReptor Cloud status page</a>.</p></details></div><div class="faq-item" id="maintenance"><details class="details custom-block"><summary>What is the maintenance window?</summary><p>Wednesdays and Saturdays, 08:00–11:00 GMT.</p><p>Planned maintenance is also announced on the <a href="https://status.sysreptor.com/" target="_blank" rel="noreferrer">SysReptor Cloud status page</a>. You can subscribe there for updates.</p></details></div>`,23),n(`div`,u,[n(`p`,d,[a(g,{icon:`mdi:help-circle`,class:`lg middle`,label:`Further questions?`})]),c[0]||=n(`p`,null,[t(`Need help or have questions? Get support and `),n(`a`,{href:`https://github.com/Syslifters/sysreptor/discussions/`,target:`_blank`,rel:`noreferrer`},`connect with us and the SysReptor community`),t(`.`)],-1)])])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};